import{_ as i,o as t,c as n,a2 as a}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"Was ist ApptiveTeams","description":"Die Mitarbeiter-App, die vollständig über einen ApptiveGrid-Space konfiguriert wird.","frontmatter":{"title":"Was ist ApptiveTeams","description":"Die Mitarbeiter-App, die vollständig über einen ApptiveGrid-Space konfiguriert wird."},"headers":[],"relativePath":"apptiveteams/was-ist-apptiveteams.md","filePath":"apptiveteams/was-ist-apptiveteams.md","lastUpdated":1786357627000}'),s={name:"apptiveteams/was-ist-apptiveteams.md"};function r(d,e,p,o,l,u){return t(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="was-ist-apptiveteams" tabindex="-1">Was ist ApptiveTeams <a class="header-anchor" href="#was-ist-apptiveteams" aria-label="Permalink to &quot;Was ist ApptiveTeams&quot;">​</a></h1><p><strong>ApptiveTeams</strong> ist eine Mitarbeiter-App für iOS und Android. Mitarbeitende melden sich mit ihrem ApptiveGrid-Konto an und sehen die Inhalte, die Sie in einem <strong>Team Space</strong> pflegen: Formulare, Links, Neuigkeiten und Webinhalte.</p><p>Der entscheidende Punkt: Die App wird <strong>vollständig über ApptiveGrid konfiguriert</strong> — ohne eine Zeile Code. Ändern Sie etwas im Team Space, erscheint die Änderung direkt in der App. Ein App-Update über den Store ist dafür nicht nötig.</p><h2 id="wie-die-konfiguration-funktioniert" tabindex="-1">Wie die Konfiguration funktioniert <a class="header-anchor" href="#wie-die-konfiguration-funktioniert" aria-label="Permalink to &quot;Wie die Konfiguration funktioniert&quot;">​</a></h2><p>Die App liest bestimmte Grids aus Ihrem Team Space. Welches Grid wofür zuständig ist, entscheidet nicht sein <strong>Name</strong>, sondern sein <strong>Key</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Team Space (Kategorie: apptiveTeams)</span></span>
<span class="line"><span>├── Grid mit Key „config&quot;    → Logo und Farbe der App</span></span>
<span class="line"><span>├── Grid mit Key „tabs&quot;      → die Tabs der Navigationsleiste</span></span>
<span class="line"><span>└── Grid mit Key „settings&quot;  → eigene Einträge im Einstellungs-Bildschirm</span></span></code></pre></div><p>Dasselbe gilt für die Felder innerhalb dieser Grids. Namen können Sie also frei vergeben — maßgeblich sind allein die Keys.</p><p>→ <a href="/apptiveteams/team-space">Den Team Space einrichten</a></p><h2 id="voraussetzungen" tabindex="-1">Voraussetzungen <a class="header-anchor" href="#voraussetzungen" aria-label="Permalink to &quot;Voraussetzungen&quot;">​</a></h2><ul><li>Ein <strong>ApptiveGrid-Konto</strong> für Ihr Unternehmen und für jede Person, die die App nutzen soll.</li><li>Ein <strong>Space mit der Kategorie <code>apptiveTeams</code></strong>. Nur solche Spaces bietet die App zur Auswahl an.</li><li>Alle Mitarbeitenden sind als <strong>Mitglieder</strong> in diesen Space eingeladen. → <a href="/zusammenarbeit/personen-einladen">Personen einladen</a></li><li>Die <strong>ApptiveTeams App</strong> aus dem App Store (iOS) oder von Google Play (Android).</li></ul><div class="tip custom-block"><p class="custom-block-title">Mit einer Vorlage starten</p><p>Einen Team Space von Grund auf aufzubauen, bedeutet, alle Grids, Keys und Felder selbst anzulegen. Für den Einstieg gibt es eine fertige Team-Space-Vorlage — sprechen Sie uns an, dann richten wir sie gemeinsam mit Ihnen ein.</p></div><h2 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to &quot;Erste Schritte&quot;">​</a></h2><ol><li><strong>App installieren</strong> — ApptiveTeams aus dem App Store oder von Google Play laden.</li><li><strong>Anmelden</strong> — mit dem ApptiveGrid-Konto. Die Anmeldung öffnet den ApptiveGrid-Login im Browser.</li><li><strong>Team auswählen</strong> — die App zeigt alle Team Spaces, in denen Sie Mitglied sind. Gibt es genau einen, wird er automatisch geöffnet.</li><li><strong>Loslegen</strong> — die App lädt Branding, Tabs und Inhalte aus dem Team Space.</li></ol><div class="tip custom-block"><p class="custom-block-title">Änderungen sofort sehen</p><p>Über das <strong>Aktualisieren-Symbol</strong> oben rechts lädt die App die Konfiguration neu. Das brauchen Sie beim Einrichten ständig — nach jeder Änderung im Team Space.</p></div><p>Über <strong>Team wechseln</strong> im Einstellungs-Bildschirm wechseln Sie später jederzeit zwischen mehreren Team Spaces.</p><h2 id="was-sie-damit-bauen-konnen" tabindex="-1">Was Sie damit bauen können <a class="header-anchor" href="#was-sie-damit-bauen-konnen" aria-label="Permalink to &quot;Was Sie damit bauen können&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anwendung</th><th>Umsetzung</th></tr></thead><tbody><tr><td>Schnellzugriff auf Formulare</td><td>Kachel-Tab mit Links auf ApptiveGrid-Formulare</td></tr><tr><td>Schwarzes Brett, Neuigkeiten</td><td>Karten-Tab mit Bild, Text und Aktions-Button</td></tr><tr><td>Intranet, Schichtplan</td><td>WebView-Tab mit der jeweiligen Adresse</td></tr><tr><td>Krankmeldung, Urlaubsantrag</td><td>Formular-Kachel, die direkt in der App geöffnet wird</td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/apptiveteams/team-space">Team Space einrichten</a></li><li><a href="/apptiveteams/tabs">Tabs einrichten</a></li><li><a href="/apptiveteams/kacheln-und-karten">Kacheln und Karten</a></li></ul>`,19)])])}const h=i(s,[["render",r]]);export{c as __pageData,h as default};
